import static org.junit.jupiter.api.Assertions.assertArrayEquals;
import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.fail;

import java.lang.invoke.MethodHandle;
import java.lang.invoke.VarHandle;
import java.util.Arrays;
import java.util.List;
import java.util.Random;

import javax.swing.RowFilter;
import javax.swing.RowSorter;
import javax.swing.SizeSequence;
import javax.swing.SortOrder;
import javax.swing.table.DefaultTableModel;
import javax.swing.table.TableRowSorter;

import sun.swing.table.M3SparseSizes;

/**
 * Patterns ADD_REMOVE_GET / INDEX_MAPPING / AGGREGATE_PREFIX / EXCEPTIONAL_INPUT: {@code M3SparseSizes} against
 * {@code javax.swing.SizeSequence} (the JDK type it mirrors) through the same {@code setSize}, {@code insertEntries},
 * {@code removeEntries} and {@code setSizes} scripts; after every step every size and position from -2 to length + 2
 * and every index around every row boundary, inside and outside the range, must be the stock answer. The view-order
 * mapping is checked against the stock {@code SortManager.setViewRowHeightsFromModel} loop over a
 * {@code TableRowSorter}.
 */
final class SizesScript {

    static final int MAX_LENGTH = 40;
    static final int STEPS = 220;
    static final int MAX_DEFAULT = 30;
    static final int MAX_SIZE = 60;
    static final int MAX_RUN = 4;
    static final int OUTSIDE = 2;
    static final int DEFAULT_ONE_IN = 4;
    static final int DENSE_MARGIN = 64;
    static final int DENSE_CHECK_EVERY = 512;
    static final int KEY_RANGE = 7;
    static final int TRIALS = 30;
    static final int FAR_POSITION = 1000;

    enum Mix {
        SET(8, 1, 1, 0), INSERT(2, 7, 1, 0), REMOVE(2, 1, 7, 0), RESET(3, 2, 2, 2), MIXED(4, 3, 3, 1);

        final int set;
        final int insert;
        final int remove;
        final int reset;

        Mix(int set, int insert, int remove, int reset) {
            this.set = set;
            this.insert = insert;
            this.remove = remove;
            this.reset = reset;
        }
    }

    final Random rnd;
    SizeSequence stock;
    M3SparseSizes m3;
    int defaultSize;

    SizesScript(String atom) {
        rnd = AtomSupport.random(atom);
        int n = rnd.nextInt(MAX_LENGTH);
        defaultSize = 1 + rnd.nextInt(MAX_DEFAULT);
        stock = new SizeSequence(n, defaultSize);
        m3 = new M3SparseSizes(n, defaultSize);
    }

    int length() {
        return stock.getSizes().length;
    }

    /** The custom (non-default) row indices in order: what the sparse lanes hold. */
    int[] customIndices() {
        int[] sizes = stock.getSizes();
        return java.util.stream.IntStream.range(0, sizes.length).filter(i -> sizes[i] != defaultSize).toArray();
    }

    void same(String what) {
        int n = length();
        assertEquals(n, m3.length(), what + ": length");
        assertArrayEquals(stock.getSizes(), m3.getSizes(), what + ": sizes");
        assertEquals(defaultSize, m3.defaultSize(), what + ": default size");
        if (m3.count() >= 0) {
            assertEquals(customIndices().length, m3.count(), what + ": sparse entries");
        }
        for (int i = -OUTSIDE; i <= n + OUTSIDE; i++) {
            assertEquals(stock.getSize(i), m3.getSize(i), what + ": getSize " + i);
            assertEquals(stock.getPosition(i), m3.getPosition(i), what + ": getPosition " + i);
        }
        for (int i = 0; i <= n; i++) {
            int p = stock.getPosition(i);
            for (int d = -1; d <= 1; d++) {
                assertEquals(stock.getIndex(p + d), m3.getIndex(p + d), what + ": getIndex " + (p + d));
            }
        }
        int total = stock.getPosition(n);
        for (int p : new int[] {-1, 0, total - 1, total, total + 1, total + FAR_POSITION, Integer.MAX_VALUE, Integer.MIN_VALUE}) {
            assertEquals(stock.getIndex(p), m3.getIndex(p), what + ": getIndex " + p);
        }
    }

    int size() {
        return rnd.nextInt(DEFAULT_ONE_IN) == 0 ? defaultSize : rnd.nextInt(MAX_SIZE);
    }

    void set() {
        int i = rnd.nextInt(length() + OUTSIDE);
        int s = size();
        stock.setSize(i, s);
        m3.setSize(i, s);
        same("setSize " + i + " " + s);
    }

    void insert() {
        int at = rnd.nextInt(length() + 1);
        int k = rnd.nextInt(MAX_RUN + 1);
        int v = size();
        stock.insertEntries(at, k, v);
        m3.insertEntries(at, k, v);
        same("insertEntries " + at + " " + k + " " + v);
    }

    void remove() {
        int at = rnd.nextInt(length() + 1);
        int k = rnd.nextInt(Math.min(MAX_RUN, length() - at) + 1);
        stock.removeEntries(at, k);
        m3.removeEntries(at, k);
        same("removeEntries " + at + " " + k);
    }

    void reset() {
        int n = rnd.nextInt(MAX_LENGTH);
        int v = 1 + rnd.nextInt(MAX_DEFAULT);
        stock = new SizeSequence(n, v);
        defaultSize = v;
        m3.setSizes(n, v);
        same("setSizes " + n + " " + v);
    }

    void run(Mix mix, int steps) {
        same("start");
        int total = mix.set + mix.insert + mix.remove + mix.reset;
        for (int step = 0; step < steps; step++) {
            int op = rnd.nextInt(total);
            if (op < mix.set) {
                set();
            } else if (op < mix.set + mix.insert) {
                insert();
            } else if (op < mix.set + mix.insert + mix.remove) {
                remove();
            } else {
                reset();
            }
        }
    }

    /** More than LIMIT custom sizes: the store turns into the stock dense tree and keeps every answer. */
    void dense() {
        int n = M3SparseSizes.LIMIT + DENSE_MARGIN;
        defaultSize = 1;
        stock = new SizeSequence(n, defaultSize);
        m3.setSizes(n, defaultSize);
        for (int i = 0; i < M3SparseSizes.LIMIT; i++) {
            stock.setSize(i, defaultSize + 1 + i % MAX_SIZE);
            m3.setSize(i, defaultSize + 1 + i % MAX_SIZE);
            if (i % DENSE_CHECK_EVERY == 0) {
                assertEquals(i + 1, m3.count());
            }
        }
        assertEquals(M3SparseSizes.LIMIT, m3.count(), "LIMIT custom sizes are still sparse");
        same("at the limit");
        stock.setSize(M3SparseSizes.LIMIT, MAX_SIZE);
        m3.setSize(M3SparseSizes.LIMIT, MAX_SIZE);
        assertEquals(-1, m3.count(), "one more custom size: dense");
        same("dense");
        run(Mix.MIXED, STEPS / 4);
        reset();
        assertEquals(0, m3.count(), "setSizes returns to the sparse form");
    }

    void denseByInsert() {
        int v = defaultSize + 1;
        stock.insertEntries(0, M3SparseSizes.LIMIT + 1, v);
        m3.insertEntries(0, M3SparseSizes.LIMIT + 1, v);
        assertEquals(-1, m3.count(), "an insert of more than LIMIT custom sizes goes dense first");
        same("dense by insert");
        stock.removeEntries(0, M3SparseSizes.LIMIT);
        m3.removeEntries(0, M3SparseSizes.LIMIT);
        same("dense remove");
    }

    void exceptional() {
        assertThrows(IllegalArgumentException.class, () -> new M3SparseSizes(-1, 1));
        assertThrows(IllegalArgumentException.class, () -> new M3SparseSizes(1, 0));
        int n = length();
        assertThrows(IndexOutOfBoundsException.class, () -> m3.insertEntries(-1, 1, 1));
        assertThrows(IndexOutOfBoundsException.class, () -> m3.insertEntries(n + 1, 1, 1));
        assertThrows(IndexOutOfBoundsException.class, () -> m3.insertEntries(0, -1, 1));
        assertThrows(IndexOutOfBoundsException.class, () -> m3.removeEntries(-1, 1));
        assertThrows(IndexOutOfBoundsException.class, () -> m3.removeEntries(0, -1));
        assertThrows(IndexOutOfBoundsException.class, () -> m3.removeEntries(0, n + 1));
        assertThrows(IllegalArgumentException.class, () -> m3.setSizes(-1, 1));
        assertThrows(IllegalArgumentException.class, () -> m3.setSizes(1, 0));
        int[] before = m3.getSizes();
        m3.setSize(-1, MAX_SIZE);
        m3.setSize(n, MAX_SIZE);
        assertArrayEquals(before, m3.getSizes(), "setSize of a negative index or one at the length changes nothing");
        same("after the rejected calls");
    }

    /** The stock {@code SortManager.setViewRowHeightsFromModel} loop as the oracle of {@code inViewOrder}. */
    void inViewOrderContract() {
        for (int trial = 0; trial < TRIALS; trial++) {
            run(Mix.SET, MAX_RUN * MAX_RUN);
            if (trial % (TRIALS / 3) == 0) {
                denseIfSmall();
            }
            int n = length();
            DefaultTableModel model = new DefaultTableModel(new Object[] {"key"}, 0) {
                @Override
                public Class<?> getColumnClass(int column) {
                    return Integer.class;
                }
            };
            for (int i = 0; i < n; i++) {
                model.addRow(new Object[] {rnd.nextInt(KEY_RANGE)});
            }
            TableRowSorter<DefaultTableModel> sorter = new TableRowSorter<>(model);
            sorter.setSortKeys(List.of(new RowSorter.SortKey(0, rnd.nextBoolean() ? SortOrder.DESCENDING : SortOrder.ASCENDING)));
            int hidden = rnd.nextInt(KEY_RANGE);
            if (rnd.nextBoolean()) {
                sorter.setRowFilter(new RowFilter<>() {
                    @Override
                    public boolean include(Entry<? extends DefaultTableModel, ? extends Integer> e) {
                        return (Integer) e.getValue(0) != hidden;
                    }
                });
            }
            int viewCount = sorter.getViewRowCount();
            SizeSequence expected = new SizeSequence(viewCount, defaultSize);
            for (int v = viewCount - 1; v >= 0; v--) {
                expected.setSize(v, stock.getSize(sorter.convertRowIndexToModel(v)));
            }
            M3SparseSizes view = m3.inViewOrder(viewCount, defaultSize, sorter);
            assertArrayEquals(expected.getSizes(), view.getSizes(), "view rows sized from their model rows");
            assertEquals(viewCount, view.length());
        }
    }

    void denseIfSmall() {
        if (m3.count() >= 0 && length() < MAX_LENGTH) {
            MethodHandle toDense = AtomSupport.virtual(M3SparseSizes.class, "toDense", void.class);
            AtomSupport.call(toDense, m3);
            assertEquals(-1, m3.count(), "toDense moves the store to the stock tree");
            same("toDense");
        }
    }

    // ---- white-box checks of the private atoms -------------------------------------------------------------

    void findContract(boolean lower) {
        MethodHandle h = AtomSupport.virtual(M3SparseSizes.class, lower ? "lowerBound" : "find", int.class, int.class);
        for (int trial = 0; trial < TRIALS; trial++) {
            run(Mix.MIXED, MAX_RUN);
            if (m3.count() < 0) {
                reset();
            }
            int[] custom = customIndices();
            for (int i = -OUTSIDE; i <= length() + OUTSIDE; i++) {
                int expected = Arrays.binarySearch(custom, i);
                if (lower) {
                    expected = expected >= 0 ? expected : -1 - expected;
                }
                assertEquals(expected, (int) AtomSupport.call(h, m3, i), (lower ? "lowerBound " : "find ") + i);
            }
        }
    }

    void prefixContract(String atom) {
        MethodHandle build = AtomSupport.virtual(M3SparseSizes.class, "build", void.class);
        MethodHandle total = AtomSupport.virtual(M3SparseSizes.class, "total", long.class);
        MethodHandle start = AtomSupport.virtual(M3SparseSizes.class, "start", long.class, int.class);
        VarHandle prefix = AtomSupport.field(M3SparseSizes.class, "prefix", long[].class);
        VarHandle dirty = AtomSupport.field(M3SparseSizes.class, "dirty", boolean.class);
        for (int trial = 0; trial < TRIALS; trial++) {
            run(Mix.MIXED, MAX_RUN);
            if (m3.count() < 0) {
                reset();
            }
            AtomSupport.call(build, m3);
            assertFalse((boolean) dirty.get(m3), "build leaves the prefix lane clean");
            int[] custom = customIndices();
            int[] sizes = stock.getSizes();
            long[] p = (long[]) prefix.get(m3);
            long sum = 0;
            for (int j = 0; j < custom.length; j++) {
                assertEquals(sum, p[j], atom + ": prefix " + j);
                assertEquals((long) stock.getPosition(custom[j]), (long) AtomSupport.call(start, m3, j), atom + ": start " + j);
                sum += sizes[custom[j]] - defaultSize;
            }
            assertEquals(sum, p[custom.length], atom + ": prefix of all entries");
            assertEquals((long) stock.getPosition(length()), (long) AtomSupport.call(total, m3), atom + ": total");
        }
    }

    void laneInsertRemove(boolean insert) {
        MethodHandle lower = AtomSupport.virtual(M3SparseSizes.class, "lowerBound", int.class, int.class);
        MethodHandle ins = AtomSupport.virtual(M3SparseSizes.class, "insert", void.class, int.class, int.class, int.class);
        MethodHandle rem = AtomSupport.virtual(M3SparseSizes.class, "remove", void.class, int.class, int.class);
        for (int trial = 0; trial < STEPS; trial++) {
            if (m3.count() < 0 || length() == 0) {
                reset();
                continue;
            }
            int[] custom = customIndices();
            int i = rnd.nextInt(length());
            boolean isCustom = Arrays.binarySearch(custom, i) >= 0;
            if (insert && !isCustom) {
                int s = defaultSize + 1 + rnd.nextInt(MAX_SIZE);
                int j = (int) AtomSupport.call(lower, m3, i);
                AtomSupport.call(ins, m3, j, i, s);
                stock.setSize(i, s);
                same("lane insert at entry " + j + " row " + i);
            } else if (!insert && custom.length > 0) {
                int j = rnd.nextInt(custom.length);
                int k = 1 + rnd.nextInt(custom.length - j);
                AtomSupport.call(rem, m3, j, k);
                for (int e = j; e < j + k; e++) {
                    stock.setSize(custom[e], defaultSize);
                }
                same("lane remove of entries " + j + ".." + (j + k - 1));
            } else {
                set();
            }
        }
    }

    // ---- per-atom checks ------------------------------------------------------------------------------------

    static void check(String atom) {
        SizesScript s = new SizesScript(atom);
        switch (atom) {
            case "M3SparseSizes" -> {
                s.same("new");
                assertEquals(0, s.m3.count(), "a new store holds no entries");
                s.exceptional();
            }
            case "getSizes", "length", "getSize", "getPosition", "getIndex" -> s.run(Mix.MIXED, STEPS);
            case "defaultSize" -> s.run(Mix.RESET, STEPS);
            case "count" -> {
                s.run(Mix.SET, STEPS);
                s.dense();
            }
            case "setSize" -> {
                s.run(Mix.SET, STEPS);
                s.exceptional();
            }
            case "insertEntries" -> {
                s.run(Mix.INSERT, STEPS);
                s.exceptional();
                s.denseByInsert();
            }
            case "removeEntries" -> {
                s.run(Mix.REMOVE, STEPS);
                s.exceptional();
            }
            case "setSizes" -> {
                s.run(Mix.RESET, STEPS);
                s.exceptional();
            }
            case "toDense" -> {
                s.dense();
                s.denseIfSmall();
                s.run(Mix.MIXED, STEPS / 2);
            }
            case "inViewOrder" -> s.inViewOrderContract();
            case "total", "start", "build" -> s.prefixContract(atom);
            case "find" -> s.findContract(false);
            case "lowerBound" -> s.findContract(true);
            case "insert" -> s.laneInsertRemove(true);
            case "remove" -> s.laneInsertRemove(false);
            default -> fail("no check for M3SparseSizes#" + atom);
        }
    }
}
